using System.Globalization;
using System.Resources;

namespace PresenceSync.Core.Resources;

/// <summary>
/// User-facing texts. English is the neutral language (Strings.resx), German in Strings.de.resx.
/// The UI language follows <see cref="CultureInfo.CurrentUICulture"/>, i.e. the Windows display language.
/// Properties are generated by scripts/Update-Strings.ps1.
/// </summary>
public static partial class Strings
{
    private static readonly ResourceManager Resources = new("PresenceSync.Core.Resources.Strings", typeof(Strings).Assembly);

    /// <summary>Text in the current UI language.</summary>
    public static string Get(string key) => Get(key, CultureInfo.CurrentUICulture);

    /// <summary>Text in the given language; falls back to English.</summary>
    public static string Get(string key, CultureInfo culture) =>
        Resources.GetString(key, culture) ?? throw new KeyNotFoundException($"Missing resource string '{key}'");

    /// <summary>Formatted text in the current UI language.</summary>
    public static string Format(string key, params object?[] args) =>
        string.Format(CultureInfo.CurrentCulture, Get(key), args);

    /// <summary>All keys of the neutral (English) resource set – used by tests.</summary>
    internal static IEnumerable<string> Keys(CultureInfo culture) =>
        Resources.GetResourceSet(culture, createIfNotExists: true, tryParents: false)!
            .Cast<System.Collections.DictionaryEntry>()
            .Select(e => (string)e.Key);
}

/// <summary>
/// A message that is shown to the user in the UI language and written to the log in English.
/// Arguments may themselves be <see cref="LocalizedMessage"/>s.
/// </summary>
public sealed record LocalizedMessage(string Key, params object?[] Args)
{
    private static readonly CultureInfo English = CultureInfo.InvariantCulture;

    /// <summary>For the user (current UI language).</summary>
    public string Text => Render(CultureInfo.CurrentUICulture, CultureInfo.CurrentCulture);

    /// <summary>For the log (English).</summary>
    public string LogText => Render(English, English);

    private string Render(CultureInfo uiCulture, CultureInfo formatCulture) =>
        string.Format(formatCulture, Strings.Get(Key, uiCulture),
            Args.Select(a => a is LocalizedMessage m ? m.Render(uiCulture, formatCulture) : a).ToArray());

    public override string ToString() => Text;
}
